CREATE TABLE [dbo].[TREC_MONITOR](	  [mon_ext_id] INT NOT NULL IDENTITY(1,1)	, [mon_extension] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [mon_activo] TINYINT NOT NULL	, [mon_graba] TINYINT NOT NULL	, [pos_pc] VARCHAR(25) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [cli_id] INT NOT NULL	, [descripcion] NVARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, [isIPExt] BIT NULL	, [IPTelefono] VARCHAR(23) COLLATE SQL_Latin1_General_CP1_CI_AS NULL	, CONSTRAINT [PK_TREC_MONITOR] PRIMARY KEY ([mon_ext_id] ASC))